<?php require 'faculty_bootstrap.php';$title='Students';$fid=(int)$_SESSION['user']['id'];$search=trim($_GET['q']??'');$offering=(int)($_GET['offering']??0);$sql="SELECT DISTINCT u.id,u.name,u.student_id,u.email,u.program,o.id offering_id,s.code,s.name subject,o.section,o.day_name,o.start_time,o.end_time,o.room FROM users u JOIN enrollments e ON e.student_id=u.id AND e.status='approved' JOIN subject_offerings o ON o.id=e.offering_id AND o.faculty_id=? JOIN subjects s ON s.id=o.subject_id WHERE u.role='student'";$p=[$fid];if($offering){$sql.=' AND o.id=?';$p[]=$offering;}if($search!==''){$sql.=' AND (u.name LIKE ? OR u.student_id LIKE ? OR u.email LIKE ? OR s.code LIKE ?)';$like='%'.$search.'%';array_push($p,$like,$like,$like,$like);}$sql.=' ORDER BY u.name,s.code';$q=$pdo->prepare($sql);$q->execute($p);$rows=$q->fetchAll();require 'header.php';
?><section class="section"><div class="section-intro"><div><span class="eyebrow">CLASS ROSTERS</span><h2>Students</h2><p class="muted">Students currently enrolled in your assigned classes.</p></div><form method="get" class="announcement-filter"><input name="q" value="<?=e($search)?>" placeholder="Search student"><button class="btn">Search</button></form></div><div class="table-scroll"><table class="table"><tr><th>Student</th><th>Student ID</th><th>Program</th><th>Class</th><th>Schedule</th><th>Room</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['name'])?></b><br><span class="muted"><?=e($r['email'])?></span></td><td><?=e($r['student_id']?:'—')?></td><td><?=e($r['program']?:'—')?></td><td><b><?=e($r['code'])?></b><br><?=e($r['subject'])?> · <?=e($r['section'])?></td><td><?=e($r['day_name'])?><br><?=date('g:i A',strtotime($r['start_time']))?>–<?=date('g:i A',strtotime($r['end_time']))?></td><td><?=e($r['room'])?></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><p class="muted">No students matched your search.</p><?php endif;?></section><?php require 'footer.php';?>
